-- Example data for the PostgreSQL schema generated by the API.
--
-- Seeded users all use:
--   password: SeedPassword123!
--
-- This script is intentionally safe to re-run. It only replaces rows whose
-- IDs/emails are part of this seed set and leaves unrelated application data
-- untouched.
--
-- Order.currentStatus and Order.baseMarket are Java enums without
-- @Enumerated(EnumType.STRING), so Hibernate stores their ordinal values:
--   Status: SUBMITTED=0, CANCELED=1, REJECTED=2, ACCEPTED=3, FILLED=4
--   BaseMarket: UNCAT=0, US=1, IN=2

BEGIN;

CREATE TEMP TABLE seed_clients (
    client_id UUID PRIMARY KEY,
    portfolio_id UUID NOT NULL,
    name TEXT NOT NULL,
    email TEXT NOT NULL
) ON COMMIT DROP;

INSERT INTO seed_clients (client_id, portfolio_id, name, email) VALUES
    ('10000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000001', 'Ava Thompson', 'ava.thompson@example.test'),
    ('10000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000002', 'Liam Chen', 'liam.chen@example.test'),
    ('10000000-0000-0000-0000-000000000003', '20000000-0000-0000-0000-000000000003', 'Maya Patel', 'maya.patel@example.test'),
    ('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000004', 'Noah Williams', 'noah.williams@example.test'),
    ('10000000-0000-0000-0000-000000000005', '20000000-0000-0000-0000-000000000005', 'Sophia Garcia', 'sophia.garcia@example.test'),
    ('10000000-0000-0000-0000-000000000006', '20000000-0000-0000-0000-000000000006', 'Ethan Brown', 'ethan.brown@example.test');

-- Remove only the previous seed set. Child rows are removed first because
-- portfolio_holdings and order_status_log have foreign keys to their owners.
DELETE FROM order_status_log
WHERE order_id IN (
    SELECT orderid FROM orders
    WHERE client_id IN (SELECT client_id FROM seed_clients)
);
DELETE FROM orders WHERE client_id IN (SELECT client_id FROM seed_clients);
DELETE FROM portfolio_snapshot
WHERE client_id IN (SELECT client_id FROM seed_clients);
DELETE FROM client_watchlist
WHERE client_id IN (SELECT client_id FROM seed_clients);
DELETE FROM portfolio_holdings
WHERE portfolio_id IN (SELECT portfolio_id FROM seed_clients);
DELETE FROM client
WHERE id IN (SELECT client_id FROM seed_clients)
   OR email IN (SELECT email FROM seed_clients);
DELETE FROM portfolio
WHERE id IN (SELECT portfolio_id FROM seed_clients);

INSERT INTO portfolio (id, totalvalue)
SELECT portfolio_id, 0 FROM seed_clients;

INSERT INTO client (
    id, name, email, passwordhash, role, tokenrevokedat, createdat, updatedat, portfolio_id
)
SELECT
    client_id,
    name,
    email,
    '$2a$12$IKf4/IIQPbhY0N6zRUk5JOUPeuRNE51RlBHE7z2oEP0h3fm/VXJmO',
    CASE WHEN row_number() OVER (ORDER BY email) = 1 THEN 'ADMIN' ELSE 'CLIENT' END,
    NULL,
    TIMESTAMPTZ '2026-01-05 09:00:00+00' + (row_number() OVER (ORDER BY email) * INTERVAL '1 day'),
    TIMESTAMPTZ '2026-01-05 09:00:00+00' + (row_number() OVER (ORDER BY email) * INTERVAL '1 day'),
    portfolio_id
FROM seed_clients;

-- Asset values are embedded in the collection tables; no standalone asset
-- table exists in the current JPA model.
INSERT INTO portfolio_holdings (
    portfolio_id, symbol, name, instrument, quantity, avgbuyprice
)
SELECT
    c.portfolio_id,
    a.symbol,
    a.name,
    a.instrument,
    a.quantity * (1 + c.client_number * 0.10),
    a.avg_buy_price
FROM (
    SELECT client_id, portfolio_id, row_number() OVER (ORDER BY email)::NUMERIC AS client_number
    FROM seed_clients
) c
CROSS JOIN (
    VALUES
        ('USD', 'US Dollar', 'CASH', 10000.00::NUMERIC, 1.00::NUMERIC),
        ('AAPL', 'Apple Inc.', 'EQUITY', 18.00::NUMERIC, 178.25::NUMERIC),
        ('MSFT', 'Microsoft Corporation', 'EQUITY', 12.00::NUMERIC, 401.10::NUMERIC),
        ('NVDA', 'NVIDIA Corporation', 'EQUITY', 9.00::NUMERIC, 121.75::NUMERIC),
        ('BTC', 'Bitcoin', 'CRYPTO', 0.18::NUMERIC, 64250.00::NUMERIC),
        ('ETH', 'Ethereum', 'CRYPTO', 2.40::NUMERIC, 3195.50::NUMERIC)
) AS a(symbol, name, instrument, quantity, avg_buy_price);

UPDATE portfolio p
SET totalvalue = h.total_value
FROM (
    SELECT portfolio_id, SUM(quantity * avgbuyprice) AS total_value
    FROM portfolio_holdings
    WHERE portfolio_id IN (SELECT portfolio_id FROM seed_clients)
    GROUP BY portfolio_id
) h
WHERE p.id = h.portfolio_id;

INSERT INTO client_watchlist (client_id, symbol, name, instrument)
SELECT
    c.client_id,
    a.symbol,
    a.name,
    a.instrument
FROM seed_clients c
CROSS JOIN (
    VALUES
        ('TSLA', 'Tesla Inc.', 'EQUITY'),
        ('AMZN', 'Amazon.com Inc.', 'EQUITY'),
        ('GOOGL', 'Alphabet Inc.', 'EQUITY'),
        ('SOL', 'Solana', 'CRYPTO')
) AS a(symbol, name, instrument);

-- Six orders per client, covering every order status across both markets.
INSERT INTO orders (
    orderid, tracking_id, client_id, buy, orderdate, price, quantity,
    currentstatus, symbol, name, instrument, basemarket
)
SELECT
    ('30000000-0000-0000-0000-' || lpad(((c.client_number - 1) * 6 + o.order_number)::TEXT, 12, '0'))::UUID,
    ('40000000-0000-0000-0000-' || lpad(((c.client_number - 1) * 6 + o.order_number)::TEXT, 12, '0'))::UUID,
    c.client_id,
    o.buy,
    TIMESTAMPTZ '2026-10-01 14:00:00+00' - ((c.client_number + o.order_number) * INTERVAL '9 hours'),
    o.price,
    o.quantity,
    o.current_status,
    o.symbol,
    o.asset_name,
    o.instrument,
    o.base_market
FROM (
    SELECT client_id, row_number() OVER (ORDER BY email)::INTEGER AS client_number
    FROM seed_clients
) c
CROSS JOIN (
    VALUES
        (1, TRUE,  'AAPL', 'Apple Inc.', 'EQUITY', 178.25::NUMERIC, 4.00::NUMERIC, 4, 1),
        (2, TRUE,  'BTC',  'Bitcoin',    'CRYPTO', 64250.00::NUMERIC, 0.05::NUMERIC, 3, 1),
        (3, FALSE, 'MSFT', 'Microsoft Corporation', 'EQUITY', 401.10::NUMERIC, 2.00::NUMERIC, 0, 2),
        (4, TRUE,  'NVDA', 'NVIDIA Corporation', 'EQUITY', 121.75::NUMERIC, 6.00::NUMERIC, 1, 1),
        (5, FALSE, 'ETH', 'Ethereum', 'CRYPTO', 3195.50::NUMERIC, 0.80::NUMERIC, 2, 1),
        (6, TRUE,  'GOOGL', 'Alphabet Inc.', 'EQUITY', 165.40::NUMERIC, 3.00::NUMERIC, 4, 2)
) AS o(order_number, buy, symbol, asset_name, instrument, price, quantity, current_status, base_market);

INSERT INTO order_status_log (order_id, status, status_change_time)
SELECT
    o.orderid,
    s.status,
    o.orderdate + s.offset_value * INTERVAL '15 minutes'
FROM orders o
CROSS JOIN (
    VALUES
        ('SUBMITTED', 0),
        ('ACCEPTED', 1),
        ('FILLED', 2)
) AS s(status, offset_value)
WHERE o.client_id IN (SELECT client_id FROM seed_clients)
  AND o.currentstatus = 4;

INSERT INTO order_status_log (order_id, status, status_change_time)
SELECT
    o.orderid,
    s.status,
    o.orderdate + INTERVAL '10 minutes'
FROM orders o
CROSS JOIN (
    VALUES
        (0, 'SUBMITTED'),
        (1, 'CANCELED'),
        (2, 'REJECTED'),
        (3, 'ACCEPTED')
) AS s(expected_status, status)
WHERE o.client_id IN (SELECT client_id FROM seed_clients)
  AND o.currentstatus = s.expected_status;

-- Thirty daily history points per client, useful for charts and performance
-- testing. Values vary deterministically, so reruns produce the same dataset.
INSERT INTO portfolio_snapshot (
    id, client_id, snapshot_timestamp, portfolio_value_usd, cash_value_usd,
    invested_value_usd, daily_change_usd
)
SELECT
    (
        '50000000-0000-' ||
        lpad(c.client_number::TEXT, 4, '0') || '-' ||
        lpad(d.day_number::TEXT, 4, '0') || '-000000000000'
    )::UUID,
    c.client_id,
    TIMESTAMPTZ '2026-09-20 21:00:00+00' + d.day_number * INTERVAL '1 day',
    (18000 + c.client_number * 1250 + d.day_number * 82 + ((d.day_number * 17 + c.client_number) % 9) * 31)::NUMERIC,
    (8200 + c.client_number * 350 - d.day_number * 12)::NUMERIC,
    (9800 + c.client_number * 900 + d.day_number * 94)::NUMERIC,
    (d.day_number * 82 + ((d.day_number * 17 + c.client_number) % 9) * 31)::NUMERIC
FROM (
    SELECT client_id, row_number() OVER (ORDER BY email)::INTEGER AS client_number
    FROM seed_clients
) c
CROSS JOIN generate_series(0, 29) AS d(day_number);

COMMIT;

